#!/usr/bin/env node
/**
 * Rebuild entry the previous tooling runs from a newly activated bundle, so
 * the project is regenerated by the new version. `plan` prints what would
 * change; `apply <digest>` applies exactly that plan. Stable interface:
 * maintenance-rebuild.mjs <project-dir> plan|apply <digest>, JSON on stdout.
 */
import { resolve } from 'node:path';
import { rebuildPlan, applyChange } from './maintenance.mjs';
import { digest, json } from './maintenance-store.mjs';
const [dir, mode, expected] = process.argv.slice(2);
try {
  const root = resolve(dir ?? '');
  const plan = rebuildPlan(root);
  const id = digest(json(plan.writes));
  const restart = plan.restart;
  if (mode === 'plan') console.log(json({ ...plan.rebuild, restart, digest: id, preview: plan.preview }));
  else if (mode === 'apply') {
    if (expected !== id) throw new Error('The project changed since the rebuild preview; nothing applied');
    applyChange(root, plan, true);
    console.log(json({ ...plan.rebuild, restart }));
  } else throw new Error('Usage: maintenance-rebuild.mjs <project-dir> plan|apply <digest>');
} catch (error) { console.error(error.message); process.exitCode = 1; }
